void PhysicalPrinterDialog::update_printer_agent_type()
{
    if (m_config == nullptr)
        return;

    Field* agent_field = m_optgroup->get_field("printer_agent");
    if (!agent_field)
        return;

    Choice* agent_choice = dynamic_cast<Choice*>(agent_field);
    if (!agent_choice)
        return;

    // Sync selection with current config value
    const std::string current_agent = m_config->opt_string("printer_agent");

    auto agents = NetworkAgentFactory::get_registered_printer_agents();
    for (size_t i = 0; i < agents.size(); ++i) {
        if (agents[i].id == current_agent) {
            agent_choice->set_value(i);
            return;
        }
    }
}

void PhysicalPrinterDialog::update_printers()
{
    wxBusyCursor wait;

    std::unique_ptr<PrintHost> host(PrintHost::get_print_host(m_config));

    wxArrayString printers;
    Field *rs = m_optgroup->get_field("printhost_port");
    try {
        if (! host->get_printers(printers))
            printers.clear();
    } catch (const HostNetworkError &err) {
        printers.clear();
        show_error(this, _L("Connection to printers connected via the print host failed.") + "\n\n" + from_u8(err.what()));
    }
    Choice *choice = dynamic_cast<Choice*>(rs);
    choice->set_values(printers);
    printers.empty() ? rs->disable() : rs->enable();
}

