void FakePrinterAgent::maybe_start_debug_console()
{
    if (!std::getenv("JUSPRIN_FAKE_PRINTER_CONSOLE"))
        return;
    // Detached rather than joined: it blocks on std::getline(std::cin, ...),
    // which nothing can interrupt short of closing stdin. This is only ever
    // enabled for a manual test session running for the app's whole
    // lifetime, so the thread simply dies with the process at exit.
    std::thread(&FakePrinterAgent::run_debug_console, this).detach();
}

void FakePrinterAgent::run_debug_console()
{
    std::cout << "[FakePrinterAgent] manual console ready. Commands:\n"
                 "  connect [dev_id]                                                  - connect (default dev_id: FAKE001)\n"
                 "  disconnect                                                        - disconnect\n"
                 "  scenario                                                          - replay the installed scenario (default or set_scenario())\n"
                 "  stop                                                              - cancel a running scenario\n"
                 "  status <state> <percent> <remaining_min> <nozzle> <nozzle_tgt> <bed> <bed_tgt>\n"
                 "                                                                    - push one custom status immediately\n"
                 "  quit                                                              - stop this console (app keeps running)\n"
              << std::endl;

    std::string line;
    while (std::getline(std::cin, line)) {
        std::istringstream iss(line);
        std::string        cmd;
        iss >> cmd;

        if (cmd.empty()) {
            continue;
        } else if (cmd == "quit" || cmd == "exit") {
            break;
        } else if (cmd == "connect") {
            std::string dev_id;
            if (!(iss >> dev_id))
                dev_id = "FAKE001";
            connect_printer(dev_id, "127.0.0.1", "", "", false);
            std::cout << "connected " << dev_id << std::endl;
        } else if (cmd == "disconnect") {
            disconnect_printer();
            std::cout << "disconnected" << std::endl;
        } else if (cmd == "scenario") {
            std::string dev_id;
            {
                std::lock_guard<std::mutex> lock(state_mutex);
                dev_id = connected_dev_id;
            }
            PrintParams params;
            params.dev_id = dev_id;
            start_local_print(params, nullptr, nullptr);
            std::cout << "scenario started" << std::endl;
        } else if (cmd == "stop") {
            cancel_scenario();
            std::cout << "scenario stopped" << std::endl;
        } else if (cmd == "status") {
            FakePrinterStatusStep step;
            if (!(iss >> step.gcode_state >> step.mc_percent >> step.mc_remaining_time >> step.nozzle_temper >>
                  step.nozzle_target_temper >> step.bed_temper >> step.bed_target_temper)) {
                std::cout << "usage: status <state> <percent> <remaining_min> <nozzle> <nozzle_tgt> <bed> <bed_tgt>" << std::endl;
                continue;
            }
            push_status(step);
            std::cout << "status pushed" << std::endl;
        } else if (cmd == "help") {
            maybe_start_debug_console(); // re-prints usage; harmless double-check on env var
        } else {
            std::cout << "unknown command: " << cmd << " (try 'help')" << std::endl;
        }
    }
}

