const std::string kConsoleDevId = "FAKE001";

// Reads one line and parses a leading integer. Returns -1 on EOF or a non-numeric line.
int read_menu_choice()
{
    std::string line;
    if (!std::getline(std::cin, line))
        return -1;
    try {
        return std::stoi(line);
    } catch (...) {
        return -1;
    }
}
